 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog'
AS $function$
BEGIN
 IF private.actor() IS NULL THEN RAISE EXCEPTION 'unavailable' USING ERRCODE='42501'; END IF;
 INSERT INTO app.workspaces(id,name,created_by) VALUES(w,title,private.actor());
